get_ipython().run_cell_magic('writefile', f'{STAGING}/e3_analysis.py', '"""Three-model E3 summaries on exactly the same complete baseline450 graph."""\nimport json\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom e1_core import (require, progress, sha256_file, sha256_bytes, atomic_csv, atomic_json,\n                     atomic_npz, freeze_json, design, reverse, build_operators)\n\ndef panel_from_collector(frame,reference,root):\n    require(len(frame)==18000 and not frame.duplicated([\'sentence_id\',\'pair\']).any(),\'MADLAD panel must be complete\')\n    require(frame.eligible.astype(str).str.lower().isin([\'true\',\'1\',\'1.0\']).all(),\'Ineligible MADLAD rows; no silent deletion\')\n    require(set(frame.pair)==set(reference[\'pairs\']) and set(frame.sentence_id)==set(reference[\'ids\']),\'Common graph/meanings changed\')\n    reference_ids=dict(zip(reference[\'ids\'],reference[\'corpus_ids\']))\n    require(frame.corpus_sentence_id.astype(str).eq(frame.sentence_id.map(reference_ids).astype(str)).all(),\'Corpus identity mismatch\')\n    matrix=frame.pivot(index=\'sentence_id\',columns=\'pair\',values=\'lm\').loc[reference[\'ids\'],reference[\'pairs\']].to_numpy(float)\n    require(np.isfinite(matrix).all(),\'Nonfinite MADLAD panel\')\n    root=Path(root)\n    return {\'study\':\'madlad\',\'Y\':matrix,\'ids\':reference[\'ids\'],\'pairs\':reference[\'pairs\'],\'languages\':reference[\'languages\'],\n            \'corpus_ids\':reference[\'corpus_ids\'],\'csv_sha256\':{\'all_rows.csv\':sha256_file(root/\'all_rows.csv\')},\n            \'run_lock_sha256\':sha256_file(root/\'run_lock.json\')}\n\ndef field_design(pairs,languages):\n    canonical=[p for p in pairs if p<reverse(p)]\n    difference=np.zeros((len(pairs),len(canonical)))\n    incidence=np.zeros((len(canonical),len(languages)))\n    for j,p in enumerate(canonical):\n        a,b=p.split(\'__\');difference[pairs.index(p),j]=1;difference[pairs.index(reverse(p)),j]=-1\n        incidence[j,languages.index(a)]=1;incidence[j,languages.index(b)]=-1\n    require(np.linalg.matrix_rank(incidence)==len(languages)-1,\'Conservative field graph disconnected\')\n    return difference,incidence,incidence@np.linalg.pinv(incidence)\n\ndef allocation_statistics(Y,W,P,H,D,G):\n    """Weighted whole-meaning statistics with an exact two-way ANOVA decomposition."""\n    weights=W/W.sum(1,keepdims=True);mu=weights@Y;grand=mu.mean(1)\n    total=weights@(Y*Y).mean(1)-grand*grand\n    direction=np.mean((mu-grand[:,None])**2,axis=1)\n    meaning=weights@(Y.mean(1)**2)-grand*grand\n    residual=total-direction-meaning\n    require(np.all(total>0) and np.all(residual>=-1e-12),\'Invalid row variance partition\')\n    require(np.allclose((direction+meaning+residual)/total,1,atol=1e-8),\'ANOVA energy closure failed\')\n    edge=mu@D;gradient=edge@G\n    energy=np.sum(edge*edge,axis=1)\n    additive=mu@P.T\n    held=mu@H.T\n    # In-sample direction-mean and same-meaning held-dyad metrics are descriptive.\n    return {\'mean_mass\':grand,\'row_direction_share\':direction/total,\'row_meaning_share\':meaning/total,\n        \'row_residual_share\':np.maximum(residual,0)/total,\n        \'additive_direction_R2\':1-np.mean((mu-additive)**2,axis=1)/np.maximum(direction,1e-30),\n        \'held_dyad_direction_R2_shared_meanings\':1-np.mean((mu-held)**2,axis=1)/np.maximum(direction,1e-30),\n        \'gradient_fraction\':np.sum(gradient*gradient,axis=1)/np.maximum(energy,1e-30),\n        \'nonconservative_residual_L2\':np.sqrt(np.sum((edge-gradient)**2,axis=1))}\n\ndef supplementary(panel,components,output,n_boot=10000,seed=20261106):\n    output=Path(output);output.mkdir(parents=True,exist_ok=True)\n    operators,_=build_operators(panel[\'pairs\'],panel[\'languages\'])\n    P=operators[\'full\'][\'both\'];H=operators[\'held\'][\'both\']\n    D,B,G=field_design(panel[\'pairs\'],panel[\'languages\'])\n    cubes={name:components.pivot(index=\'sentence_id\',columns=\'pair\',values=name).loc[panel[\'ids\'],panel[\'pairs\']].to_numpy(float)\n           for name in [\'lexical\',\'eos\',\'language_control\',\'punctuation\',\'unknown\',\'conditional_lexical\',\'lexical_with_unknown\']}\n    require(all(np.isfinite(v).all() for v in cubes.values()),\'Nonfinite component panel\')\n    require(np.allclose(sum(cubes[k] for k in [\'lexical\',\'eos\',\'language_control\',\'punctuation\',\'unknown\']),1,atol=1e-5),\n            \'Aggregated component closure failed\')\n    signature={\'code_sha256\':sha256_file(__file__),\'study\':panel[\'study\'],\'input\':panel[\'csv_sha256\'],\n        \'component_hash\':sha256_bytes(components.sort_values([\'sentence_id\',\'pair\']).to_csv(index=False).encode()),\n        \'n_boot\':n_boot,\'seed\':seed,\'unit\':\'whole meanings jointly across all directions\',\n        \'null\':\'independent random permutation of the 20 observed signed edge values, conditional on fixed graph\'}\n    freeze_json(output/\'allocation_lock.json\',signature)\n    fingerprint=sha256_bytes(json.dumps(signature,sort_keys=True).encode())\n    cache=output/\'allocation_bootstrap.npz\'\n    # The recorded NLLB unknown component is identically zero because its baseline\n    # includes unknown tokens in lexical mass. No zero-variance R² is interpreted.\n    names=[k for k in cubes if k!=\'unknown\']\n    atomic_csv(output/\'component_means.csv\',pd.DataFrame([{\'study\':panel[\'study\'],\'component\':k,\'mean_mass\':float(v.mean())} for k,v in cubes.items()]))\n    point={k:allocation_statistics(cubes[k],np.ones((1,len(panel[\'ids\']))),P,H,D,G) for k in names}\n    metrics=list(point[names[0]])\n    if cache.is_file():\n        with np.load(cache,allow_pickle=False) as f:\n            require(str(f[\'fingerprint\'])==fingerprint,\'Allocation bootstrap cache differs\')\n            samples=f[\'samples\'];null=f[\'null\']\n    else:\n        samples=np.empty((n_boot,len(names),len(metrics)));null=np.empty(n_boot)\n        rng=np.random.default_rng(seed);edge=panel[\'Y\'].mean(0)@D\n        for start in range(0,n_boot,128):\n            count=min(128,n_boot-start);W=rng.multinomial(len(panel[\'ids\']),np.full(len(panel[\'ids\']),1/len(panel[\'ids\'])),size=count)\n            for ci,name in enumerate(names):\n                values=allocation_statistics(cubes[name],W,P,H,D,G)\n                samples[start:start+count,ci,:]=np.column_stack([values[m] for m in metrics])\n            perm=np.stack([rng.permutation(edge) for _ in range(count)])\n            null[start:start+count]=np.sum((perm@G)**2,axis=1)/np.sum(perm*perm,axis=1)\n            if start==0 or (start+count)//1024>start//1024:progress(f\'{panel["study"]}: allocation bootstrap {start+count:,}/{n_boot:,}\')\n        atomic_npz(cache,fingerprint=np.array(fingerprint),samples=samples,null=null)\n    require(samples.shape==(n_boot,len(names),len(metrics)) and np.isfinite(samples).all(),\'Invalid allocation bootstrap cache\')\n    rows=[]\n    for ci,name in enumerate(names):\n        for mi,metric in enumerate(metrics):\n            lo,hi=np.quantile(samples[:,ci,mi],[.025,.975])\n            rows.append({\'study\':panel[\'study\'],\'component\':name,\'metric\':metric,\'estimate\':float(point[name][metric][0]),\n                \'ci_low\':float(lo),\'ci_high\':float(hi),\'ci_unit\':\'meaning; fixed languages/graph; percentile\'})\n    atomic_csv(output/\'component_variance_field_metrics.csv\',pd.DataFrame(rows))\n    lexical_edge=panel[\'Y\'].mean(0)@D;theta=np.linalg.pinv(B)@lexical_edge\n    coef=np.linalg.pinv(design(panel[\'pairs\'],panel[\'languages\'],\'both\'))@panel[\'Y\'].mean(0)\n    n=len(panel[\'languages\']);alpha=coef[1:1+n];beta=coef[1+n:1+2*n]\n    require(np.allclose(theta,alpha-beta,atol=1e-10),\'Potential/additive coefficient identity failed\')\n    atomic_csv(output/\'full450_language_coefficients.csv\',pd.DataFrame({\'study\':panel[\'study\'],\'language\':panel[\'languages\'],\n        \'alpha\':alpha,\'beta\':beta,\'theta\':theta}))\n    observed=float(point[\'lexical\'][\'gradient_fraction\'][0])\n    atomic_json(output/\'edge_permutation_null.json\',{\'observed_gradient_fraction\':observed,\'null_mean\':float(null.mean()),\n        \'null_q95\':float(np.quantile(null,.95)),\'p_plus_one\':float((1+(null>=observed).sum())/(n_boot+1)),\n        \'repetitions\':n_boot,\'null\':signature[\'null\'],\n        \'limit\':\'Descriptive edge-exchangeability null; not a model of sentence noise or new-language generalization.\'})\n    return pd.DataFrame(rows)\n')


