get_ipython().run_cell_magic('writefile', f'{STAGING}/e6_core.py', '"""E6 generation-path alignment, fp32 causal replay, and immutable checkpoints."""\nimport hashlib\nimport json\nfrom collections import Counter\nfrom pathlib import Path\nfrom e1_core import require, atomic_json\nfrom e3_worker import punctuation\n\n\ndef canonical(value):\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\',\', \':\')).encode()).hexdigest()\n\n\ndef trim_sequence(values, eos_id):\n    values = list(map(int, values))\n    ends = [i for i, value in enumerate(values) if i > 0 and value == int(eos_id)]\n    return values[:ends[0]+1] if ends else values\n\n\ndef generation_flags(text, reference, ids, eos_id, limit=256):\n    words = str(text).split()\n    triples = list(zip(words, words[1:], words[2:]))\n    ends = len(ids) > 1 and ids[-1] == int(eos_id)\n    empty = not str(text).strip()\n    repetitive = bool(len(words) >= 8 and Counter(words).most_common(1)[0][1]/len(words) > .5)\n    return {\'empty_output\': empty, \'degenerate\': bool(empty or repetitive),\n            \'repeated_word_trigram\': bool(triples and max(Counter(triples).values()) >= 3),\n            \'ended_with_eos\': ends, \'generation_hit_cap\': bool(not ends and len(ids) >= limit),\n            \'generation_reaches_limit\': bool(len(ids) >= limit),\n            \'generated_length\': len(ids),\n            \'length_ratio_chars\': sum(not c.isspace() for c in str(text))/max(1, sum(not c.isspace() for c in str(reference)))}\n\n\ndef label_rows(sequence, study, tok, target_decoder=None):\n    """Rows predict sequence[1:], never the decoder-start token at sequence[0].\n\n    EOS/pad/language controls are excluded. NLLB retains unknown, whereas IT2\n    and MADLAD exclude it. Cap-hit sequences need no fabricated terminal EOS.\n    """\n    labels = list(map(int, sequence[1:]))\n    pieces = ([target_decoder[i] for i in labels] if study == \'it2\'\n              else tok.convert_ids_to_tokens(labels))\n    excluded = set(map(int, tok.all_special_ids))\n    if study == \'nllb\':\n        excluded.discard(int(tok.unk_token_id))\n    rows, controls = [], 0\n    for i, (token, piece) in enumerate(zip(labels, pieces)):\n        language_control = str(piece).startswith(\'<2\') and str(piece).endswith(\'>\')\n        if token in excluded or language_control:\n            controls += int(token not in {int(tok.eos_token_id), int(tok.pad_token_id), int(tok.unk_token_id)})\n            continue\n        if not punctuation(piece):\n            rows.append(i)\n    return rows, controls\n\n\ndef decoder_batch(sequences, pad_id, device):\n    import torch\n    require(sequences and all(len(seq) >= 2 for seq in sequences), \'No generated prediction step\')\n    steps = max(len(seq)-1 for seq in sequences)\n    decoder = torch.full((len(sequences), steps), int(pad_id), dtype=torch.long, device=device)\n    attention = torch.zeros_like(decoder)\n    labels = torch.full_like(decoder, -100)\n    for b, seq in enumerate(sequences):\n        length = len(seq)-1\n        decoder[b, :length] = torch.tensor(seq[:-1], dtype=torch.long, device=device)\n        attention[b, :length] = 1\n        labels[b, :length] = torch.tensor(seq[1:], dtype=torch.long, device=device)\n    return decoder, attention, labels\n\n\ndef replay(model, x, sequences, pad_id):\n    """No labels= round-trip/shift: decoder inputs are the exact generated prefix."""\n    import torch\n    from types import SimpleNamespace\n    device = next(model.parameters()).device\n    decoder, mask, labels = decoder_batch(sequences, pad_id, device)\n    encoder = model.get_encoder()(input_ids=x.input_ids.to(device), attention_mask=x.attention_mask.to(device),\n                                  output_attentions=False, return_dict=True)\n    # Sinusoidal decoder positions in the IT2/M2M100 family can advance by\n    # cache length even across generated PAD IDs. A full-prefix cumsum over\n    # non-PAD IDs can then differ. Replay such batches with native caching.\n    needs_cache = any(int(pad_id) in seq[:-1] for seq in sequences)\n    if not needs_cache:\n        out = model(encoder_outputs=encoder, attention_mask=x.attention_mask.to(device),\n                    decoder_input_ids=decoder, decoder_attention_mask=mask,\n                    use_cache=False, output_attentions=True, return_dict=True)\n        out.replay_mode = \'full_prefix\'\n        return out, labels\n    past = None\n    if getattr(model, \'_supports_cache_class\', False):\n        from transformers.cache_utils import DynamicCache, EncoderDecoderCache\n        past = EncoderDecoderCache(DynamicCache(), DynamicCache())\n    logits, attention = [], []\n    for step in range(decoder.shape[1]):\n        out = model(encoder_outputs=encoder, attention_mask=x.attention_mask.to(device),\n                    decoder_input_ids=decoder[:, step:step+1], decoder_attention_mask=mask[:, :step+1],\n                    past_key_values=past, use_cache=True, output_attentions=True, return_dict=True)\n        past = out.past_key_values\n        logits.append(out.logits)\n        attention.append(out.cross_attentions)\n    layers = tuple(torch.cat([step[layer] for step in attention], dim=2)\n                   for layer in range(len(attention[0])))\n    return SimpleNamespace(logits=torch.cat(logits, dim=1), cross_attentions=layers,\n                           replay_mode=\'cached_generated_PAD\'), labels\n\n\ndef cached_member_attention(cached, member, length):\n    """HF decode step t predicts generated sequence[t+1]."""\n    import torch\n    require(len(cached) >= length, \'Decode-step attention list is shorter than generated prefix\')\n    n_layers = len(cached[0])\n    return tuple(torch.stack([cached[t][layer][member, :, -1, :] for t in range(length)], dim=1).unsqueeze(0)\n                 for layer in range(n_layers))\n\n\ndef compare_cached_replay(cached, replayed, member, length):\n    direct = cached_member_attention(cached, member, length)\n    require(len(direct) == len(replayed), \'Cached/replayed decoder layer counts differ\')\n    return max(float((a[0]-b[member, :, :length, :]).abs().max()) for a, b in zip(direct, replayed))\n\n\ndef save_generation(path, fingerprint, rows):\n    """One atomic envelope, not an independently overwritten CSV/hash pair."""\n    atomic_json(path, {\'fingerprint\': fingerprint, \'payload_sha256\': canonical(rows), \'rows\': rows})\n\n\ndef load_generation(path, fingerprint, expected_ids):\n    value = json.loads(Path(path).read_text())\n    require(value[\'fingerprint\'] == fingerprint and value[\'payload_sha256\'] == canonical(value[\'rows\']),\n            \'Generation checkpoint identity/content changed\')\n    require([row[\'sentence_id\'] for row in value[\'rows\']] == expected_ids, \'Generation checkpoint meaning order changed\')\n    return value[\'rows\']\n\n\ndef ordered_chunks(group, reused_ids, chunk_size=20):\n    require(chunk_size == 20, \'Frozen checkpoint size changed\')\n    reuse = [row for row in group if row[\'sentence_id\'] in reused_ids]\n    fresh = [row for row in group if row[\'sentence_id\'] not in reused_ids]\n    require(len(reuse) == 20 and len(fresh) == 430, \'Expected E5 baseline20 plus430 new meanings\')\n    # E5 batches were sorted within its20, so this preserves the reused batch contexts.\n    return [reuse]+[fresh[i:i+chunk_size] for i in range(0, len(fresh), chunk_size)]\n')


