get_ipython().run_cell_magic('writefile', f'{STAGING}/e6_worker.py', '"""E6: unablated fp32 greedy paths, verified causal attention replay, all450 meanings."""\nimport argparse\nimport gc\nimport importlib.metadata\nimport json\nimport os\nimport sys\nimport time\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom e1_core import progress, require, sha256_file, atomic_csv, atomic_json, atomic_npz, freeze_json\nfrom e3_worker import load_texts, prepare_records, positions\nfrom e4_masks import FINE_COMPONENTS, finer_positions, aggregate_attention, outcomes_from_means\nfrom e6_core import (canonical, trim_sequence, generation_flags, label_rows, replay,\n                     cached_member_attention, compare_cached_replay, save_generation, load_generation, ordered_chunks)\n\n\ndef run(config):\n    require(os.environ.get(\'PYTHONHASHSEED\') == \'0\', \'Start worker with PYTHONHASHSEED=0\')\n    for name, expected in config[\'sources\'].items():\n        require(sha256_file(Path(__file__).parent/name) == expected, \'Changed source: \'+name)\n    progress(\'Importing pinned fp32 GPU libraries...\')\n    import torch\n    import sacrebleu\n    from transformers import T5Tokenizer, T5ForConditionalGeneration\n    from huggingface_hub import snapshot_download\n    require(torch.cuda.is_available(), \'L4 GPU required; CPU model inference is not started\')\n    torch.manual_seed(config[\'seed\'])\n    np.random.seed(config[\'seed\'])\n    torch.backends.cuda.matmul.allow_tf32 = False\n    torch.backends.cudnn.allow_tf32 = False\n    torch.backends.cudnn.benchmark = False\n    torch.backends.cudnn.deterministic = True\n    torch.set_float32_matmul_precision(\'highest\')\n    study = config[\'study\']\n    root = Path(config[\'output\']);root.mkdir(parents=True, exist_ok=True)\n    e4 = Path(config[\'e4_root\'])/\'collectors\'/study\n    e5 = Path(config[\'e5_root\'])/\'collectors\'/study\n    e4_complete = json.loads((e4/\'complete.json\').read_text())\n    e5_complete = json.loads((e5/\'complete.json\').read_text())\n    require(sha256_file(e4/\'complete.json\') == config[\'e4_completion_sha256\'], \'E4 completion changed\')\n    require(sha256_file(e5/\'complete.json\') == config[\'e5_completion_sha256\'], \'E5 completion changed\')\n    require(sha256_file(e4/\'all_rows.csv\') == e4_complete[\'all_rows_sha256\'] and\n            sha256_file(e4/\'private_tokenization/input_ids.csv\') == e4_complete[\'token_ids_sha256\'], \'E4 input changed\')\n    old = pd.read_csv(e4/\'all_rows.csv\', dtype={\'corpus_sentence_id\': str}).set_index([\'pair\', \'sentence_id\'])\n    token_frame = pd.read_csv(e4/\'private_tokenization/input_ids.csv\', dtype={\'corpus_sentence_id\': str})\n    frozen = {(r.pair, r.sentence_id): (json.loads(r.source_ids_json), json.loads(r.reference_ids_json))\n              for r in token_frame.itertuples(index=False)}\n    require(len(old) == len(frozen) == 18000 and not old.index.duplicated().any(), \'Incomplete E4 input panel\')\n    e5_lock = json.loads((e5/\'run_lock.json\').read_text())\n    require(sha256_file(e5/\'run_lock.json\') == e5_complete[\'run_lock_sha256\'], \'E5 model lock changed\')\n    require(e5_lock[\'token_ids_sha256\'] == e4_complete[\'token_ids_sha256\'], \'E5 and E4 encoder inputs differ\')\n    path = e5/\'private_generation/all_outputs.csv\'\n    require(sha256_file(path) == e5_complete[\'generation_sha256\'], \'E5 generation outputs changed\')\n    previous = pd.read_csv(path, dtype={\'corpus_sentence_id\': str}, keep_default_na=False)\n    previous = previous[previous.condition == \'baseline\']\n    require(len(previous) == 800 and not previous.duplicated([\'pair\', \'sentence_id\']).any(), \'Expected E5 baseline20 × 40\')\n    reuse_ids = set(map(int, e5_lock[\'generation_ids\']))\n    require(len(reuse_ids) == 20 and set(previous.sentence_id) == reuse_ids, \'E5 generation subset changed\')\n    reuse = previous.set_index([\'pair\', \'sentence_id\'])\n    manifest = pd.read_csv(config[\'manifest\'], dtype={\'corpus_sentence_id\': str})\n    require(sha256_file(config[\'manifest\']) == config[\'manifest_sha256\'], \'Original corpus identity changed\')\n    records = prepare_records(manifest, load_texts(config))\n    groups = {}\n    for record in records:groups.setdefault(record[\'pair\'], []).append(record)\n    ids = sorted(config[\'split\'][\'train\']+config[\'split\'][\'validation\']+config[\'split\'][\'test\'])\n    require(len(ids) == len(set(ids)) == 450 and len(groups) == 40, \'Frozen panel changed\')\n    for group in groups.values():\n        group.sort(key=lambda r: r[\'sentence_id\'])\n        require([r[\'sentence_id\'] for r in group] == ids, \'Missing original meanings\')\n    require(set(frozen) == set(old.index) == {(r[\'pair\'], r[\'sentence_id\']) for r in records}, \'Inputs are not aligned\')\n    if study == \'it2\':\n        sys.path.insert(0, config[\'indic_library\'])\n        os.environ[\'INDIC_RESOURCES_PATH\'] = config[\'indic_resources\']\n    if study in [\'it2\', \'nllb\']:\n        from original_adapter import Adapter\n        ad = Adapter(study);tok, model = ad.tok, ad.model\n        spec = {\'repo\': ad.name, \'revision\': ad.model_rev}\n    else:\n        spec = json.loads((e4/\'run_lock.json\').read_text())[\'model\']\n        progress(\'Loading/verifying the existing pinned MADLAD checkpoint...\')\n        directory = snapshot_download(spec[\'repo\'], revision=spec[\'revision\'], local_dir=config[\'madlad_cache\'], allow_patterns=list(spec[\'files\']))\n        for name, expected in spec[\'files\'].items():require(sha256_file(Path(directory)/name) == expected, \'MADLAD asset changed: \'+name)\n        tok = T5Tokenizer.from_pretrained(directory, local_files_only=True, legacy=False)\n        model = T5ForConditionalGeneration.from_pretrained(directory, local_files_only=True, use_safetensors=True,\n            torch_dtype=torch.float32, low_cpu_mem_usage=True, attn_implementation=\'eager\', device_map={\'\': \'cuda:0\'}).eval()\n    require(all(p.dtype == torch.float32 and p.device.type == \'cuda\' for p in model.parameters()), \'Expected fp32 CUDA model\')\n    require(getattr(model.config, \'_attn_implementation\', \'eager\') == \'eager\', \'Eager attention required\')\n    require(tok.pad_token_id == model.config.pad_token_id, \'Tokenizer/model padding IDs disagree\')\n    require((spec[\'repo\'], spec[\'revision\']) == (e5_lock[\'model\'][\'repo\'], e5_lock[\'model\'][\'revision\']), \'Checkpoint changed\')\n    batch_size = 4 if study in [\'it2\', \'nllb\'] else 1\n    options = {\'max_length\': 256, \'min_length\': 0, \'num_beams\': 1, \'do_sample\': False, \'use_cache\': True,\n               \'output_attentions\': False, \'output_scores\': False, \'return_dict_in_generate\': True}\n    require(options == e5_lock[\'generation\'] and batch_size == e5_lock[\'generation_batch_size\'], \'E5 decoding policy changed\')\n    signature = {\'study\': study, \'model\': spec, \'sources\': config[\'sources\'], \'split\': config[\'split\'],\n        \'e4_completion_sha256\': config[\'e4_completion_sha256\'], \'e5_completion_sha256\': config[\'e5_completion_sha256\'],\n        \'manifest_sha256\': config[\'manifest_sha256\'], \'seed\': config[\'seed\'], \'python_hash_seed\': 0,\n        \'precision\': \'fp32\', \'TF32\': False, \'attention\': \'eager\', \'generation\': options,\n        \'generation_config\': model.generation_config.to_dict(), \'batch_size\': batch_size,\n        \'batch_policy\': \'sorted E5 baseline20 in original batches, then sorted430 new meanings; chunks20\',\n        \'attention_method\': \'causal replay of exact generated IDs, decoder inputs sequence[:-1], labels sequence[1:], no text retokenization\',\n        \'PAD_handling\': \'native cached replay if any actual decoder-input token is PAD; full-prefix replay otherwise\',\n        \'reference_TF\': \'reuse immutable E4 fine-component rows; no new full reference collection\',\n        \'smoke_attention_max_tolerance\': 1e-4, \'smoke_head_component_tolerance\': 1e-5,\n        \'gpu\': torch.cuda.get_device_name(0), \'packages\': {p: importlib.metadata.version(p) for p in\n            [\'torch\', \'transformers\', \'numpy\', \'pandas\', \'sentencepiece\', \'sacrebleu\']}}\n    freeze_json(root/\'run_lock.json\', signature)\n    fingerprint = canonical(signature)\n    device = next(model.parameters()).device\n    decoder_start = model.generation_config.decoder_start_token_id\n    if decoder_start is None:decoder_start = model.config.decoder_start_token_id\n\n    def encode_source(block):\n        record = block[0];ip = None\n        if study == \'it2\':\n            ip = ad.IndicProcessor(inference=True)\n            texts = ip.preprocess_batch([r[\'src_text\'] for r in block], src_lang=record[\'source\'], tgt_lang=record[\'target\'])\n            x = tok(texts, return_tensors=\'pt\', padding=True, truncation=True, max_length=256, return_attention_mask=True)\n        elif study == \'nllb\':\n            tok.src_lang = record[\'source\'];tok.tgt_lang = record[\'target\'];tok.set_src_lang_special_tokens(record[\'source\'])\n            x = tok([r[\'src_text\'] for r in block], return_tensors=\'pt\', padding=True, truncation=True,\n                    max_length=256, return_attention_mask=True)\n        else:\n            prefix = \'<2\'+config[\'language_codes\'][record[\'target\']]+\'>\'\n            x = tok([prefix+\' \'+r[\'src_text\'] for r in block], return_tensors=\'pt\', padding=True, truncation=False)\n        for b, r in enumerate(block):\n            actual = x.input_ids[b][x.attention_mask[b].bool()].tolist()\n            require(actual == frozen[(r[\'pair\'], r[\'sentence_id\'])][0], f\'Encoder IDs changed: {r["pair"]} / {r["sentence_id"]}\')\n        return x, ip\n\n    def fine_source(x, b, record):\n        values, mask = x.input_ids[b].tolist(), x.attention_mask[b].tolist()\n        if study in [\'it2\', \'nllb\']:\n            base = ad.categories(values, mask, record[\'source\'], record[\'target\']);pieces = ad.pieces(values)\n        else:\n            prefix_id = tok.convert_tokens_to_ids(\'<2\'+config[\'language_codes\'][record[\'target\']]+\'>\')\n            base = positions(tok, values, mask, prefix_id);pieces = tok.convert_ids_to_tokens(values)\n        return finer_positions(base, values, pieces, int(tok.unk_token_id))\n\n    def generate(block, cached_attention=False):\n        x, ip = encode_source(block)\n        opts = dict(options);opts[\'output_attentions\'] = cached_attention\n        if study == \'nllb\':opts[\'forced_bos_token_id\'] = ad.language_id(block[0][\'target\'])\n        with torch.inference_mode():\n            out = model.generate(input_ids=x.input_ids.to(device), attention_mask=x.attention_mask.to(device), **opts)\n        sequences = [trim_sequence(seq.tolist(), tok.eos_token_id) for seq in out.sequences]\n        require(all(len(seq) >= 2 and seq[0] == decoder_start for seq in sequences), \'Unexpected generated decoder prefix\')\n        if study == \'nllb\':require(all(seq[1] == ad.language_id(block[0][\'target\']) for seq in sequences), \'Forced target tag changed\')\n        texts = tok.batch_decode(out.sequences, skip_special_tokens=True, clean_up_tokenization_spaces=(study == \'it2\'))\n        if ip is not None:texts = ip.postprocess_batch(texts, lang=block[0][\'target\'])\n        require(len(texts) == len(sequences) == len(block), \'Incomplete generation/postprocessing\')\n        rows = []\n        for r, text, seq in zip(block, texts, sequences):\n            row = {k: r[k] for k in [\'pair\', \'sentence_id\', \'corpus_sentence_id\', \'source\', \'target\']}\n            row.update({\'source_text\': r[\'src_text\'], \'reference\': r[\'tgt_text\'], \'hypothesis\': str(text),\n                \'generated_ids_json\': json.dumps(seq), \'hyp_sha256\': canonical(str(text)),\n                \'source_sha256\': canonical(r[\'src_text\']), \'reference_sha256\': canonical(r[\'tgt_text\']),\n                \'reused_E5\': False, \'chrfpp\': float(sacrebleu.sentence_chrf(str(text), [r[\'tgt_text\']], word_order=2).score),\n                **generation_flags(str(text), r[\'tgt_text\'], seq, tok.eos_token_id)})\n            rows.append(row)\n        return rows, x, out if cached_attention else None\n\n    def target_metadata(record):\n        if study == \'it2\':\n            tp = ad.IndicProcessor(inference=False)\n            texts = tp.preprocess_batch([record[\'tgt_text\']], src_lang=record[\'target\'], tgt_lang=record[\'source\'], is_target=True)\n            full = tok(text_target=texts, return_tensors=\'pt\', padding=False, truncation=False, add_special_tokens=True)\n        elif study == \'nllb\':\n            tok.src_lang = record[\'source\'];tok.tgt_lang = record[\'target\'];tok.set_src_lang_special_tokens(record[\'source\'])\n            full = tok(text_target=[record[\'tgt_text\']], return_tensors=\'pt\', padding=False, truncation=False, add_special_tokens=True)\n        else:full = tok(record[\'tgt_text\'], return_tensors=\'pt\', truncation=False)\n        full_ids = full.input_ids[0].tolist();stored = frozen[(record[\'pair\'], record[\'sentence_id\'])][1]\n        require(len(full_ids) >= len(stored), \'Uncapped reference shorter than recorded E4 input\')\n        if len(full_ids) == len(stored):require(full_ids == stored, \'Untruncated reference tokenization changed\')\n        return {\'reference_input_tokens\': len(stored), \'reference_full_tokens\': len(full_ids),\n                \'reference_was_truncated\': len(full_ids) > len(stored)}\n\n    # Verify both returned-step alignment and numerical agreement across all heads.\n    progress(study+\': smoke — cached decode attention versus causal prefix replay...\')\n    parity = [];smoke_validation = [];smoke_reproduction = []\n    chosen_pairs = sorted(groups)[:2]\n    for pair in chosen_pairs:\n        candidates = [r for r in groups[pair] if r[\'sentence_id\'] in config[\'split\'][\'validation\']]\n        probe = [candidates[0]]\n        generated, x, direct = generate(probe, cached_attention=True)\n        smoke_validation.extend(generated)\n        plain, _, _ = generate(probe, cached_attention=False)\n        require(generated[0][\'generated_ids_json\'] == plain[0][\'generated_ids_json\'], \'Attention-output flag changed greedy path\')\n        seq = json.loads(generated[0][\'generated_ids_json\'])\n        with torch.inference_mode():\n            out, _ = replay(model, x, [seq], tok.pad_token_id)\n        delta = compare_cached_replay(direct.cross_attentions, out.cross_attentions, 0, len(seq)-1)\n        require(delta <= 1e-4, \'Cached/replay attention mismatch; stop without relaxing tolerance\')\n        target_rows, _ = label_rows(seq, study, tok, ad.tok.tgt_decoder if study == \'it2\' else None)\n        component_delta = None\n        if target_rows:\n            fine = fine_source(x, 0, probe[0])\n            a, _ = aggregate_attention(cached_member_attention(direct.cross_attentions, 0, len(seq)-1), fine, target_rows)\n            b, _ = aggregate_attention(out.cross_attentions, fine, target_rows)\n            component_delta = float(np.max(np.abs(a-b)))\n            require(component_delta <= 1e-5, \'Per-head component cached/replay mismatch\')\n        # A genuinely uncapped greedy prefix exercises the cap/no-EOS row rule.\n        prefix = seq[:min(6, len(seq)-1 if seq[-1] == tok.eos_token_id else len(seq))]\n        short_delta = None\n        if len(prefix) >= 2:\n            with torch.inference_mode():short, _ = replay(model, x, [prefix], tok.pad_token_id)\n            short_delta = compare_cached_replay(direct.cross_attentions, short.cross_attentions, 0, len(prefix)-1)\n            require(short_delta <= 1e-4, \'Capped-prefix attention alignment failed\')\n            del short\n        parity.append({\'pair\': pair, \'max_attention_delta\': delta, \'max_component_delta\': component_delta,\n                       \'prefix_max_attention_delta\': short_delta, \'steps\': len(seq)-1})\n        del direct, out\n    reuse_timing = []\n    for pair in chosen_pairs:\n        block = [r for r in groups[pair] if r[\'sentence_id\'] in reuse_ids][:batch_size]\n        tic = time.perf_counter();generated, x, cached = generate(block, cached_attention=True)\n        generation_elapsed = time.perf_counter()-tic\n        smoke_reproduction.extend(generated)\n        for row in generated:\n            expected = reuse.loc[(pair, row[\'sentence_id\'])]\n            require(json.loads(row[\'generated_ids_json\']) == json.loads(expected.generated_ids_json), \'E5 baseline greedy IDs no longer reproduce\')\n            require(row[\'hypothesis\'] == expected.hypothesis, \'E5 decoded text no longer reproduces\')\n        sequences = [json.loads(row[\'generated_ids_json\']) for row in generated]\n        with torch.inference_mode():checked, _ = replay(model, x, sequences, tok.pad_token_id)\n        deltas = [compare_cached_replay(cached.cross_attentions, checked.cross_attentions, b, len(seq)-1)\n                  for b, seq in enumerate(sequences)]\n        require(max(deltas) <= 1e-4, \'Batched cached/replay attention parity failed\')\n        prefixes = [seq[:min(6, len(seq)-1 if seq[-1] == tok.eos_token_id else len(seq))] for seq in sequences]\n        # An empty output has no non-EOS prediction prefix. Keep it intact for\n        # this numerical check; it is never omitted from the actual panel.\n        prefixes = [prefix if len(prefix) >= 2 else seq for prefix, seq in zip(prefixes, sequences)]\n        with torch.inference_mode():prefix_out, _ = replay(model, x, prefixes, tok.pad_token_id)\n        prefix_deltas = [compare_cached_replay(cached.cross_attentions, prefix_out.cross_attentions, b, len(seq)-1)\n                         for b, seq in enumerate(prefixes)]\n        require(max(prefix_deltas) <= 1e-4, \'Batched no-EOS-prefix attention parity failed\')\n        parity.append({\'pair\': pair, \'case\': \'original_E5_batch\', \'batch_size\': len(block),\n                       \'max_attention_delta\': max(deltas), \'prefix_max_attention_delta\': max(prefix_deltas)})\n        del cached, checked, prefix_out\n        reuse_timing.append(generation_elapsed/len(block))\n    atomic_json(root/\'private_generation/smoke_outputs.json\',\n                {\'validation\': smoke_validation, \'E5_reproduction\': smoke_reproduction})\n    atomic_json(root/\'smoke_report.json\', {\'passed\': True, \'cached_replay_parity\': parity,\n        \'E5_reuse_token_IDs_reproduced\': True, \'seconds_per_generation_in_smoke_batches\': float(np.mean(reuse_timing)),\n        \'rough_new_generation_hours\': float(np.mean(reuse_timing)*17200/3600),\n        \'estimate_excludes\': \'replay, setup, Drive and CPU analysis; smoke lengths may not represent all meanings\',\n        \'peak_gpu_GiB\': torch.cuda.max_memory_allocated()/2**30})\n    progress(f\'{study}: smoke passed; rough new-generation compute {np.mean(reuse_timing)*17200/3600:.2f} h, plus replay/IO\')\n    frames, all_generated = [], []\n    for pi, pair in enumerate(sorted(groups), 1):\n        chunks = ordered_chunks(groups[pair], reuse_ids)\n        for ci, chunk in enumerate(chunks):\n            folder = root/\'parts\'/pair\n            folder.mkdir(parents=True, exist_ok=True)\n            generated_path = folder/\'private_generation\'/f\'{ci:03d}.json\'\n            csv, npz, stamp = [folder/(f\'{ci:03d}\'+suffix) for suffix in [\'.csv\', \'.npz\', \'.json\']]\n            expected_ids = [r[\'sentence_id\'] for r in chunk]\n            if generated_path.is_file():\n                generated = load_generation(generated_path, fingerprint, expected_ids)\n            elif ci == 0:\n                generated = []\n                for r in chunk:\n                    previous_row = reuse.loc[(pair, r[\'sentence_id\'])]\n                    require(previous_row.source_text == r[\'src_text\'] and previous_row.reference == r[\'tgt_text\'] and\n                            str(previous_row.corpus_sentence_id) == r[\'corpus_sentence_id\'], \'Reused corpus identity mismatch\')\n                    row = previous_row.to_dict();row.update(pair=pair, sentence_id=int(r[\'sentence_id\']), reused_E5=True)\n                    row[\'generation_reaches_limit\'] = int(row[\'generated_length\']) >= 256\n                    require(row[\'hyp_sha256\'] == canonical(row[\'hypothesis\']), \'Reused hypothesis changed\')\n                    row.pop(\'condition\', None)\n                    generated.append(row)\n                save_generation(generated_path, fingerprint, generated)\n            else:\n                generated = [];tic = time.perf_counter()\n                for start in range(0, len(chunk), batch_size):\n                    new, _, _ = generate(chunk[start:start+batch_size]);generated.extend(new)\n                save_generation(generated_path, fingerprint, generated)\n                progress(f\'{study} {pi}/40 {pair}: generated chunk {ci+1}/{len(chunks)}; {time.perf_counter()-tic:.1f}s\')\n            if stamp.is_file():\n                saved = json.loads(stamp.read_text())\n                require(saved[\'fingerprint\'] == fingerprint and saved[\'CSV_sha256\'] == sha256_file(csv) and\n                        saved[\'NPZ_sha256\'] == sha256_file(npz), \'Attention checkpoint changed\')\n                frame = pd.read_csv(csv, dtype={\'corpus_sentence_id\': str})\n                require(frame.sentence_id.tolist() == expected_ids, \'Attention checkpoint support changed\')\n            else:\n                rows, head_rows = [], [];tic = time.perf_counter()\n                for start in range(0, len(chunk), batch_size):\n                    block = chunk[start:start+batch_size];g = generated[start:start+batch_size]\n                    sequences = [json.loads(row[\'generated_ids_json\']) for row in g]\n                    require(all(seq[0] == decoder_start for seq in sequences), \'Cached decoder-start token changed\')\n                    x, _ = encode_source(block)\n                    with torch.inference_mode():\n                        out, labels = replay(model, x, sequences, tok.pad_token_id)\n                        for b, (record, sequence, generation_row) in enumerate(zip(block, sequences, g)):\n                            target_rows, controls = label_rows(sequence, study, tok, ad.tok.tgt_decoder if study == \'it2\' else None)\n                            row = {k: record[k] for k in [\'pair\', \'sentence_id\', \'corpus_sentence_id\', \'source\', \'target\']}\n                            row.update({k: generation_row[k] for k in [\'reused_E5\', \'empty_output\', \'degenerate\',\n                                \'repeated_word_trigram\', \'ended_with_eos\', \'generation_hit_cap\', \'generated_length\',\n                                \'generation_reaches_limit\', \'length_ratio_chars\', \'chrfpp\']})\n                            row.update(target_metadata(record))\n                            row.update(eligible=bool(target_rows), reason=\'\' if target_rows else \'no_generated_lexical_tokens\',\n                                       generated_lexical_tokens=len(target_rows), generated_control_tokens=controls,\n                                       generated_unknown_tokens=sum(token == int(tok.unk_token_id) for token in sequence[1:]),\n                                       replay_mode=out.replay_mode)\n                            if target_rows:\n                                shares, closure = aggregate_attention(tuple(a[b:b+1] for a in out.cross_attentions), fine_source(x, b, record), target_rows)\n                                means = dict(zip(FINE_COMPONENTS, map(float, shares.mean((0, 1), dtype=np.float64))))\n                                row.update(means);row.update(outcomes_from_means(means, study == \'nllb\'));row[\'closure_maxerr\'] = closure\n                                losses = torch.nn.functional.cross_entropy(out.logits[b].float(), labels[b], reduction=\'none\', ignore_index=-100)\n                                row[\'greedy_path_lexical_NLL\'] = float(losses[target_rows].mean())\n                            else:\n                                shape = (len(out.cross_attentions), out.cross_attentions[0].shape[1], len(FINE_COMPONENTS))\n                                shares = np.full(shape, np.nan, dtype=np.float32)\n                                for name in FINE_COMPONENTS+[\'raw_lm\', \'conditional_no_separator\', \'conditional_original\',\n                                    \'raw_P_only\', \'lexical_no_unknown\', \'conditional_P_only_no_separator\',\n                                    \'conditional_no_separator_no_unknown\', \'closure_maxerr\', \'greedy_path_lexical_NLL\']:row[name] = np.nan\n                            rows.append(row);head_rows.append(shares)\n                    del out, labels\n                frame = pd.DataFrame(rows)\n                require(frame.sentence_id.tolist() == expected_ids, \'Replay output order changed\')\n                atomic_csv(csv, frame)\n                atomic_npz(npz, shares=np.stack(head_rows), columns=np.array(FINE_COMPONENTS, dtype=\'U24\'),\n                           sentence_id=np.array(expected_ids), eligible=frame.eligible.to_numpy(bool))\n                atomic_json(stamp, {\'fingerprint\': fingerprint, \'CSV_sha256\': sha256_file(csv), \'NPZ_sha256\': sha256_file(npz),\n                                    \'generation_envelope_sha256\': sha256_file(generated_path)})\n                progress(f\'{study} {pi}/40 {pair}: replay chunk {ci+1}/{len(chunks)}; {len(frame)} rows, {time.perf_counter()-tic:.1f}s\')\n            frames.append(frame);all_generated.extend(generated)\n        gc.collect();torch.cuda.empty_cache()\n    result = pd.concat(frames, ignore_index=True).sort_values([\'pair\', \'sentence_id\'])\n    for column in [\'eligible\', \'reused_E5\', \'generation_hit_cap\', \'empty_output\', \'degenerate\',\n                   \'repeated_word_trigram\', \'ended_with_eos\', \'reference_was_truncated\', \'generation_reaches_limit\']:\n        result[column] = result[column].astype(str).str.lower().isin([\'true\', \'1\', \'1.0\'])\n    require(len(result) == 18000 and not result.duplicated([\'pair\', \'sentence_id\']).any(), \'Incomplete generation panel\')\n    require(result.groupby(\'sentence_id\').pair.nunique().eq(40).all(), \'An original row was silently removed\')\n    require(result.reused_E5.astype(str).str.lower().isin([\'true\', \'1\']).sum() == 800, \'E5 reuse count differs\')\n    atomic_csv(root/\'all_rows.csv\', result)\n    atomic_csv(root/\'private_generation/all_outputs.csv\', pd.DataFrame(all_generated).sort_values([\'pair\', \'sentence_id\']))\n    atomic_json(root/\'complete.json\', {\'fingerprint\': fingerprint, \'run_lock_sha256\': sha256_file(root/\'run_lock.json\'),\n        \'rows_sha256\': sha256_file(root/\'all_rows.csv\'), \'generation_sha256\': sha256_file(root/\'private_generation/all_outputs.csv\'),\n        \'rows\': len(result), \'reused_generation_rows\': 800, \'new_generation_rows\': 17200,\n        \'ineligible_attention_rows\': int((~result.eligible).sum()), \'cap_hit_rows\': int(result.generation_hit_cap.sum()),\n        \'length_limit_rows\': int(result.generation_reaches_limit.sum())})\n    progress(study+\': all18,000 rows retained; free-generation path attention collected, no ablation\')\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser();parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


# %% original code cell 8; notebook cell 18
get_ipython().run_cell_magic('writefile', f'{STAGING}/e6_analysis.py', '"""Matched E6 regime statistics, common-support audit and paired meaning bootstraps."""\nimport argparse\nimport json\nimport importlib.metadata\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nfrom scipy.stats import rankdata\nfrom e1_core import progress, require, sha256_file, atomic_csv, atomic_json, atomic_npz, freeze_json, build_operators, design\nfrom e3_analysis import field_design\nfrom e4_masks import FINE_COMPONENTS\nfrom e6_core import canonical\n\nOUTCOMES = [\'raw_lm\', \'conditional_no_separator\']\n\n\ndef truth(series):\n    return series.astype(str).str.lower().isin([\'true\', \'1\', \'1.0\'])\n\n\ndef divide(a, b):\n    return np.divide(a, b, out=np.full(np.broadcast_shapes(np.shape(a), np.shape(b)), np.nan), where=np.asarray(b) > 1e-20)\n\n\ndef field_stats(y, weights, operators, difference, gradient):\n    w = weights/weights.sum(1, keepdims=True)\n    mean = w@y;grand = mean.mean(1)\n    total = w@(y*y).mean(1)-grand*grand\n    direction = np.mean((mean-grand[:, None])**2, axis=1)\n    meaning = w@(y.mean(1)**2)-grand*grand\n    interaction = total-direction-meaning\n    require(np.all(interaction >= -1e-12), \'Variance decomposition failed\')\n    edge = mean@difference\n    fitted = edge@gradient\n    energy = np.sum(edge*edge, axis=1)\n    additive = mean@operators[\'full\'][\'both\'].T\n    return {\'mean_LM\': grand, \'row_direction_share\': divide(direction, total),\n        \'row_meaning_share\': divide(meaning, total), \'row_interaction_share\': divide(np.maximum(interaction, 0), total),\n        \'gradient_fraction\': divide(np.sum(fitted*fitted, axis=1), energy),\n        \'edge_energy\': energy, \'gradient_energy\': np.sum(fitted*fitted, axis=1),\n        \'nonconservative_energy\': np.sum((edge-fitted)**2, axis=1),\n        \'residual_L2\': np.sqrt(np.sum((edge-fitted)**2, axis=1)),\n        \'additive_direction_R2_descriptive\': 1-divide(np.mean((mean-additive)**2, axis=1), direction)}\n\n\ndef prediction_stats(test, prediction, weights):\n    w = weights/weights.sum(1, keepdims=True)\n    mean = w@test\n    second = w@(test*test).mean(1)\n    mse = second-2*np.mean(mean*prediction[None], axis=1)+np.mean(prediction*prediction)\n    variance = second-mean.mean(1)**2\n    dmse = np.mean((mean-prediction[None])**2, axis=1)\n    dvar = np.mean((mean-mean.mean(1, keepdims=True))**2, axis=1)\n    return {\'row_R2\': 1-divide(mse, variance), \'direction_R2\': 1-divide(dmse, dvar),\n            \'row_MAE\': w@np.abs(test-prediction[None]).mean(1), \'row_RMSE\': np.sqrt(np.maximum(mse, 0)),\n            \'direction_MAE\': np.mean(np.abs(mean-prediction[None]), axis=1), \'direction_RMSE\': np.sqrt(dmse)}\n\n\ndef ci(values):\n    values = np.asarray(values)\n    finite = values[np.isfinite(values)]\n    return (*np.quantile(finite, [.025, .975]), len(finite)) if len(finite) else (np.nan, np.nan, 0)\n\n\ndef rank_rho(a, b):\n    a = rankdata(a, axis=-1);b = rankdata(b, axis=-1)\n    a -= a.mean(-1, keepdims=True);b -= b.mean(-1, keepdims=True)\n    return divide(np.sum(a*b, axis=-1), np.sqrt(np.sum(a*a, axis=-1)*np.sum(b*b, axis=-1)))\n\n\ndef matrices(frames, ids, pairs, outcome):\n    return {key: frame.pivot(index=\'sentence_id\', columns=\'pair\', values=outcome).loc[ids, pairs].to_numpy(float)\n            for key, frame in frames.items()}\n\n\ndef analyze(frames, split, output, n_boot=10000, seed=20261116):\n    output = Path(output);output.mkdir(parents=True, exist_ok=True)\n    studies = [\'it2\', \'nllb\', \'madlad\']\n    all_ids = sorted(split[\'train\']+split[\'validation\']+split[\'test\'])\n    pairs = sorted(frames[(\'it2\', \'TF\')].pair.unique())\n    languages = sorted({language for pair in pairs for language in pair.split(\'__\')})\n    operators, audit = build_operators(pairs, languages)\n    atomic_csv(output/\'E6_graph_identifiability.csv\', audit)\n    exclusions = []\n    support_sets = []\n    behavior = []\n    reference_identity = frames[(\'it2\', \'TF\')].set_index([\'pair\', \'sentence_id\']).corpus_sentence_id.sort_index()\n    for study in studies:\n        for regime in [\'TF\', \'FG\']:\n            frame = frames[(study, regime)]\n            require(len(frame) == 18000 and not frame.duplicated([\'pair\', \'sentence_id\']).any(), \'Incomplete regime input\')\n            require(set(frame.pair) == set(pairs) and set(frame.sentence_id) == set(all_ids), \'Regime identities differ\')\n            require(frame.groupby(\'sentence_id\').corpus_sentence_id.nunique().eq(1).all(), \'Meaning IDs disagree\')\n            require(frame.set_index([\'pair\', \'sentence_id\']).corpus_sentence_id.sort_index().equals(reference_identity),\n                    \'Cross-model corpus identities differ\')\n            selected = frame if regime == \'TF\' else frame[truth(frame.eligible)]\n            require(np.isfinite(selected[FINE_COMPONENTS]).all().all() and\n                    np.allclose(selected[FINE_COMPONENTS].sum(1), 1, atol=1e-5, rtol=0), \'Component closure failed\')\n            expected_LM = selected.content+(selected.unknown if study == \'nllb\' else 0.)\n            require(np.allclose(selected.raw_lm, expected_LM, atol=1e-6, rtol=0), \'Lexical/unknown convention changed\')\n        tf, fg = frames[(study, \'TF\')], frames[(study, \'FG\')]\n        merged = tf[[\'pair\', \'sentence_id\', \'corpus_sentence_id\']].merge(fg[[\'pair\', \'sentence_id\', \'corpus_sentence_id\']],\n                    on=[\'pair\', \'sentence_id\'], validate=\'one_to_one\', suffixes=(\'_TF\', \'_FG\'))\n        require(merged.corpus_sentence_id_TF.eq(merged.corpus_sentence_id_FG).all(), \'TF/FG corpus identity mismatch\')\n        eligible = truth(fg.eligible)\n        valid = fg.assign(_eligible=eligible).groupby(\'sentence_id\')._eligible.all()\n        support_sets.append(set(valid[valid].index))\n        for row in fg[~eligible].itertuples(index=False):\n            exclusions.append({\'study\': study, \'sentence_id\': row.sentence_id, \'pair\': row.pair,\n                               \'reason\': row.reason, \'attention_undefined\': True, \'behavior_row_retained\': True})\n        behavior.append({\'study\': study, \'generated_rows\': len(fg), \'attention_eligible_rows\': int(eligible.sum()),\n            \'no_lexical_attention_rows\': int((~eligible).sum()), \'generation_cap_hits\': int(truth(fg.generation_hit_cap).sum()),\n            \'generation_length_limit_rows\': int(truth(fg.generation_reaches_limit).sum()),\n            \'empty_outputs\': int(truth(fg.empty_output).sum()), \'degenerate_outputs\': int(truth(fg.degenerate).sum()),\n            \'repeated_trigram_outputs\': int(truth(fg.repeated_word_trigram).sum()),\n            \'LID_off_target_outputs\': int(truth(fg.off_target).sum()), \'mean_chrFpp_all_outputs\': float(fg.chrfpp.mean()),\n            \'reused_E5_generations\': int(truth(fg.reused_E5).sum()),\n            \'cached_generated_PAD_replay_rows\': int(fg.replay_mode.eq(\'cached_generated_PAD\').sum()),\n            \'reference_TF_target_truncated_rows\': int(truth(fg.reference_was_truncated).sum()),\n            \'source_input_truncated_rows\': int(truth(tf.source_was_truncated).sum())})\n    common = sorted(set.intersection(*support_sets))\n    require(len(common) >= 200, \'Fewer than200 complete cross-model meanings; inspect failures rather than silently weakening support\')\n    atomic_csv(output/\'E6_attention_undefined_rows.csv\', pd.DataFrame(exclusions,\n               columns=[\'study\', \'sentence_id\', \'pair\', \'reason\', \'attention_undefined\', \'behavior_row_retained\']))\n    atomic_csv(output/\'E6_generation_behavior_all_rows.csv\', pd.DataFrame(behavior))\n    membership = pd.DataFrame({\'sentence_id\': all_ids, \'in_primary_common_support\': [sid in common for sid in all_ids]})\n    for study, supported in zip(studies, support_sets):membership[study+\'_all40_eligible\'] = membership.sentence_id.isin(supported)\n    atomic_csv(output/\'E6_meaning_support_audit.csv\', membership)\n    train = [sid for sid in split[\'train\'] if sid in common]\n    test = [sid for sid in split[\'test\'] if sid in common]\n    validation = [sid for sid in split[\'validation\'] if sid in common]\n    require(len(train) >= 100 and len(test) >= 20, \'Insufficient retained train/test meaning support\')\n    atomic_json(output/\'E6_primary_support.json\', {\'original_meanings\': 450, \'common_complete_meanings\': common,\n        \'train\': train, \'validation\': validation, \'test\': test, \'no_resplit\': True,\n        \'definition\': \'all40 directions have lexical FG rows in all3 models; TF and FG use identical meanings\',\n        \'cap_hits_retained_in_primary\': True, \'undefined_rows_retained_in_behavior_counts\': True})\n    all_rows, differences, coefficients, null_rows, component_rows, language_rows = [], [], [], [], [], []\n    prediction_rows = []\n    difference, incidence, gradient = field_design(pairs, languages)\n    coefficient_op = np.linalg.pinv(design(pairs, languages, \'both\'))\n    train_idx = [common.index(sid) for sid in train];test_idx = [common.index(sid) for sid in test]\n    for outcome in OUTCOMES:\n        values = matrices(frames, common, pairs, outcome)\n        require(all(np.isfinite(y).all() for y in values.values()), \'Nonfinite primary attention matrix\')\n        points = {};samples = {};predictions = {};prediction_points = {};prediction_samples = {}\n        for key, y in values.items():\n            points[key] = field_stats(y, np.ones((1, len(common))), operators, difference, gradient)\n            samples[key] = {metric: np.empty(n_boot) for metric in points[key]}\n            for role in [\'mean\', \'source\', \'target\', \'both\']:\n                pred = operators[\'held\'][role]@y[train_idx].mean(0)\n                k = (*key, role);predictions[k] = pred\n                for j, pair in enumerate(pairs):\n                    prediction_rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome, \'model\': role,\n                        \'pair\': pair, \'observed_test_direction_mean\': float(y[test_idx, j].mean()),\n                        \'prediction_from_training\': float(pred[j]), \'training_meanings\': len(train), \'test_meanings\': len(test),\n                        \'both_dyad_directions_excluded\': True})\n                prediction_points[k] = prediction_stats(y[test_idx], pred, np.ones((1, len(test))))\n                prediction_samples[k] = {metric: np.empty(n_boot) for metric in prediction_points[k]}\n        rng = np.random.default_rng(seed)\n        test_rng = np.random.default_rng(seed+1)\n        for start in range(0, n_boot, 128):\n            count = min(128, n_boot-start)\n            w = rng.multinomial(len(common), np.full(len(common), 1/len(common)), size=count)\n            wt = test_rng.multinomial(len(test), np.full(len(test), 1/len(test)), size=count)\n            for key, y in values.items():\n                stats = field_stats(y, w, operators, difference, gradient)\n                for metric, result in stats.items():samples[key][metric][start:start+count] = result\n                for role in [\'mean\', \'source\', \'target\', \'both\']:\n                    k = (*key, role)\n                    stats = prediction_stats(y[test_idx], predictions[k], wt)\n                    for metric, result in stats.items():prediction_samples[k][metric][start:start+count] = result\n            if start == 0 or (start+count)//1024 > start//1024:\n                progress(f\'E6 {outcome}: joint meaning bootstrap {start+count:,}/{n_boot:,}\')\n        for key in values:\n            for metric, point in points[key].items():\n                lo, hi, count = ci(samples[key][metric]);estimate = float(point[0])\n                all_rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome, \'analysis\': \'all_common_meanings_descriptive\',\n                    \'model\': \'\', \'metric\': metric, \'estimate\': estimate, \'ci_low\': lo, \'ci_high\': hi,\n                    \'valid_bootstraps\': count, \'meanings\': len(common), \'point_outside_percentile_CI\': bool(estimate < lo or estimate > hi)})\n            for role in [\'mean\', \'source\', \'target\', \'both\']:\n                k = (*key, role)\n                for metric, point in prediction_points[k].items():\n                    lo, hi, count = ci(prediction_samples[k][metric]);estimate = float(point[0])\n                    all_rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome,\n                        \'analysis\': \'strict_unseen_meanings_and_dyad\', \'model\': role, \'metric\': metric,\n                        \'estimate\': estimate, \'ci_low\': lo, \'ci_high\': hi, \'valid_bootstraps\': count, \'meanings\': len(test),\n                        \'point_outside_percentile_CI\': bool(estimate < lo or estimate > hi)})\n        field_names = list(next(iter(samples.values())))\n        prediction_names = list(next(iter(prediction_samples.values())))\n        keys = list(values)\n        atomic_npz(output/(outcome+\'_bootstrap.npz\'),\n            field=np.stack([np.column_stack([samples[key][metric] for metric in field_names]) for key in keys], axis=1),\n            prediction=np.stack([np.column_stack([prediction_samples[(*key, role)][metric] for metric in prediction_names])\n                                 for key in keys for role in [\'mean\', \'source\', \'target\', \'both\']], axis=1),\n            field_axes=np.array([key[0]+\'__\'+key[1] for key in keys], dtype=\'U32\'),\n            prediction_axes=np.array([key[0]+\'__\'+key[1]+\'__\'+role for key in keys for role in [\'mean\', \'source\', \'target\', \'both\']], dtype=\'U64\'),\n            field_metrics=np.array(field_names, dtype=\'U64\'), prediction_metrics=np.array(prediction_names, dtype=\'U64\'))\n        for study in studies:\n            a, b = (study, \'TF\'), (study, \'FG\')\n            for metric in points[a]:\n                lo, hi, count = ci(samples[b][metric]-samples[a][metric])\n                differences.append({\'study\': study, \'outcome\': outcome, \'analysis\': \'all_common_meanings_descriptive\',\n                    \'metric\': metric, \'FG_minus_TF\': float(points[b][metric][0]-points[a][metric][0]),\n                    \'ci_low\': lo, \'ci_high\': hi, \'valid_bootstraps\': count})\n            for metric in prediction_points[(*a, \'both\')]:\n                ka, kb = (*a, \'both\'), (*b, \'both\')\n                lo, hi, count = ci(prediction_samples[kb][metric]-prediction_samples[ka][metric])\n                differences.append({\'study\': study, \'outcome\': outcome, \'analysis\': \'strict_both_models\', \'metric\': metric,\n                    \'FG_minus_TF\': float(prediction_points[kb][metric][0]-prediction_points[ka][metric][0]),\n                    \'ci_low\': lo, \'ci_high\': hi, \'valid_bootstraps\': count})\n        # Refit coefficients jointly on resampled training meanings; no test values enter.\n        train_rng = np.random.default_rng(seed+2)\n        coefficient_points = {key: coefficient_op@y[train_idx].mean(0) for key, y in values.items()}\n        correlations = {study: {term: np.empty(n_boot) for term in [\'beta\', \'theta\']} for study in studies}\n        n = len(languages)\n        for key, coef in coefficient_points.items():\n            theta_hodge = np.linalg.pinv(incidence)@(values[key][train_idx].mean(0)@difference)\n            require(np.allclose(theta_hodge, coef[1:1+n]-coef[1+n:1+2*n], atol=1e-10),\n                    \'Potential/additive coefficient alignment failed\')\n            for j, language in enumerate(languages):\n                coefficients.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome, \'language\': language,\n                    \'alpha\': float(coef[1+j]), \'beta\': float(coef[1+n+j]), \'theta\': float(coef[1+j]-coef[1+n+j])})\n        for start in range(0, n_boot, 128):\n            count = min(128, n_boot-start)\n            w = train_rng.multinomial(len(train), np.full(len(train), 1/len(train)), size=count)\n            fit = {key: (w@y[train_idx]/len(train))@coefficient_op.T for key, y in values.items()}\n            for study in studies:\n                a, b = fit[(study, \'TF\')], fit[(study, \'FG\')]\n                correlations[study][\'beta\'][start:start+count] = rank_rho(a[:, 1+n:1+2*n], b[:, 1+n:1+2*n])\n                correlations[study][\'theta\'][start:start+count] = rank_rho(a[:, 1:1+n]-a[:, 1+n:1+2*n], b[:, 1:1+n]-b[:, 1+n:1+2*n])\n        for study in studies:\n            a, b = coefficient_points[(study, \'TF\')], coefficient_points[(study, \'FG\')]\n            for term in [\'beta\', \'theta\']:\n                aa = a[1+n:1+2*n] if term == \'beta\' else a[1:1+n]-a[1+n:1+2*n]\n                bb = b[1+n:1+2*n] if term == \'beta\' else b[1:1+n]-b[1+n:1+2*n]\n                lo, hi, count = ci(correlations[study][term])\n                language_rows.append({\'study\': study, \'outcome\': outcome, \'term\': term,\n                    \'Spearman_TF_vs_FG\': float(rank_rho(aa, bb)), \'ci_low\': lo, \'ci_high\': hi,\n                    \'valid_bootstraps\': count, \'n_languages\': 11, \'interpretation\': \'effect size; fixed languages, training-meaning refits only\'})\n        null_rng = np.random.default_rng(seed+3)\n        for key, y in values.items():\n            edge = y.mean(0)@difference;energy = np.dot(edge, edge)\n            null = np.empty(n_boot)\n            for i in range(n_boot):\n                shuffled = null_rng.permutation(edge)\n                null[i] = np.dot(shuffled@gradient, shuffled@gradient)/energy if energy > 1e-20 else np.nan\n            observed = float(points[key][\'gradient_fraction\'][0])\n            valid = null[np.isfinite(null)]\n            null_rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome, \'observed\': observed,\n                \'null_mean\': float(valid.mean()) if len(valid) else np.nan,\n                \'null_q95\': float(np.quantile(valid, .95)) if len(valid) else np.nan,\n                \'p_plus_one\': (1+int((valid >= observed).sum()))/(len(valid)+1) if len(valid) else np.nan,\n                \'interpretation\': \'signed edge-value permutation conditional on fixed graph; not sentence-noise/new-language null\'})\n        # Prespecified cap sensitivity: same retained meanings in all6 regime panels.\n        uncapped = set(common)\n        for study in studies:\n            fg = frames[(study, \'FG\')]\n            uncapped -= set(fg.loc[truth(fg.generation_reaches_limit), \'sentence_id\'])\n            uncapped -= set(fg.loc[truth(fg.reference_was_truncated), \'sentence_id\'])\n        atomic_json(output/\'E6_uncapped_support.json\', {\'meaning_ids\': sorted(uncapped),\n            \'count\': len(uncapped), \'definition\': \'all40 directions, all3 models: FG length below limit and no reference TF truncation\',\n            \'descriptive_sensitivity_reported\': len(uncapped) >= 20})\n        if len(uncapped) >= 20:\n            uncapped = sorted(uncapped)\n            for key, frame in frames.items():\n                y = frame.pivot(index=\'sentence_id\', columns=\'pair\', values=outcome).loc[uncapped, pairs].to_numpy(float)\n                stats = field_stats(y, np.ones((1, len(uncapped))), operators, difference, gradient)\n                sensitivity_samples = {metric: np.empty(n_boot) for metric in stats}\n                sensitivity_rng = np.random.default_rng(seed+4)\n                for start in range(0, n_boot, 128):\n                    count = min(128, n_boot-start)\n                    w = sensitivity_rng.multinomial(len(uncapped), np.full(len(uncapped), 1/len(uncapped)), size=count)\n                    sampled = field_stats(y, w, operators, difference, gradient)\n                    for metric, result in sampled.items():sensitivity_samples[metric][start:start+count] = result\n                for metric, value in stats.items():\n                    lo, hi, count = ci(sensitivity_samples[metric])\n                    all_rows.append({\'study\': key[0], \'regime\': key[1], \'outcome\': outcome,\n                        \'analysis\': \'globally_uncapped_sensitivity_descriptive\', \'model\': \'\', \'metric\': metric,\n                        \'estimate\': float(value[0]), \'ci_low\': lo, \'ci_high\': hi,\n                        \'valid_bootstraps\': count, \'meanings\': len(uncapped),\n                        \'point_outside_percentile_CI\': bool(float(value[0]) < lo or float(value[0]) > hi)})\n    observed_language_rows, observed_direction_rows = [], []\n    for key, frame in frames.items():\n        selected = frame[frame.sentence_id.isin(common)]\n        for component in FINE_COMPONENTS:\n            component_rows.append({\'study\': key[0], \'regime\': key[1], \'component\': component,\n                                    \'mean_mass\': float(selected[component].mean()), \'common_meanings\': len(common)})\n        for role in [\'source\', \'target\']:\n            for language, group in selected.groupby(role):\n                observed_language_rows.append({\'study\': key[0], \'regime\': key[1], \'role\': role, \'language\': language,\n                    \'rows\': len(group), \'observed_directions\': group.pair.nunique(),\n                    \'mean_LM\': float(group.raw_lm.mean()), \'conditional_no_separator\': float(group.conditional_no_separator.mean()),\n                    \'mean_EOS\': float(group.eos.mean()), \'mean_blank\': float(group.blank.mean()),\n                    \'weighting\': \'equal observed direction-sentence rows; descriptive, not adjusted language coefficients\'})\n        for pair, group in selected.groupby(\'pair\'):\n            observed_direction_rows.append({\'study\': key[0], \'regime\': key[1], \'pair\': pair, \'meanings\': len(group),\n                \'mean_LM\': float(group.raw_lm.mean()), \'conditional_no_separator\': float(group.conditional_no_separator.mean()),\n                \'mean_EOS\': float(group.eos.mean()), \'mean_blank\': float(group.blank.mean())})\n    summary = pd.DataFrame(all_rows)\n    atomic_csv(output/\'E6_regime_statistics.csv\', summary)\n    atomic_csv(output/\'E6_paired_FG_minus_TF.csv\', pd.DataFrame(differences))\n    atomic_csv(output/\'E6_training_language_coefficients.csv\', pd.DataFrame(coefficients))\n    atomic_csv(output/\'E6_language_rank_stability.csv\', pd.DataFrame(language_rows))\n    atomic_csv(output/\'E6_edge_permutation_null.csv\', pd.DataFrame(null_rows))\n    atomic_csv(output/\'E6_fine_component_means.csv\', pd.DataFrame(component_rows))\n    atomic_csv(output/\'E6_language_means.csv\', pd.DataFrame(observed_language_rows))\n    atomic_csv(output/\'E6_direction_means.csv\', pd.DataFrame(observed_direction_rows))\n    atomic_csv(output/\'E6_held_dyad_direction_predictions.csv\', pd.DataFrame(prediction_rows))\n    # Compact paper table: all output-quality counts, matched attention estimates.\n    paper = []\n    for study in studies:\n        for regime in [\'TF\', \'FG\']:\n            subset = summary[(summary.study == study) & (summary.regime == regime) & (summary.outcome == \'raw_lm\')]\n            row = {\'study\': study, \'regime\': regime, \'original_rows\': 18000, \'common_attention_meanings\': len(common),\n                   \'train_meanings\': len(train), \'test_meanings\': len(test), \'primary_attention_rows\': len(common)*40,\n                   \'full_panel_attention_eligible_rows\': 18000 if regime == \'TF\' else int(truth(frames[(study, \'FG\')].eligible).sum())}\n            for metric in [\'mean_LM\', \'gradient_fraction\', \'row_direction_share\']:\n                q = subset[(subset.analysis == \'all_common_meanings_descriptive\') & (subset.metric == metric)].iloc[0]\n                row[metric] = q.estimate\n            for metric in [\'direction_R2\', \'row_R2\', \'direction_MAE\', \'row_RMSE\']:\n                row[\'strict_\'+metric] = subset[(subset.analysis == \'strict_unseen_meanings_and_dyad\') &\n                                               (subset.model == \'both\') & (subset.metric == metric)].estimate.iloc[0]\n            row[\'mean_EOS_mass\'] = next(r[\'mean_mass\'] for r in component_rows if r[\'study\'] == study and r[\'regime\'] == regime and r[\'component\'] == \'eos\')\n            counts = next(r for r in behavior if r[\'study\'] == study)\n            row[\'generation_length_limit_rate\'] = counts[\'generation_length_limit_rows\']/18000 if regime == \'FG\' else np.nan\n            row[\'LID_off_target_rate\'] = counts[\'LID_off_target_outputs\']/18000 if regime == \'FG\' else np.nan\n            row[\'reference_target_truncation_rate\'] = counts[\'reference_TF_target_truncated_rows\']/18000 if regime == \'TF\' else np.nan\n            paper.append(row)\n    atomic_csv(output/\'E6_main_table.csv\', pd.DataFrame(paper))\n    return pd.DataFrame(paper)\n\n\ndef run(config):\n    import fasttext\n    from huggingface_hub import hf_hub_download\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    root = Path(config[\'output\']);root.mkdir(parents=True, exist_ok=True)\n    for name, expected in config[\'sources\'].items():require(sha256_file(Path(__file__).parent/name) == expected, \'Changed E6 analysis source\')\n    spec = config[\'lid\']\n    require(json.loads(Path(config[\'lid_lock\']).read_text()) == spec, \'GlotLID revision changed\')\n    progress(\'Loading the same pinned GlotLID; no COMET scoring is required for E6...\')\n    lid_path = hf_hub_download(spec[\'repo\'], spec[\'filename\'], revision=spec[\'revision\'])\n    lid = fasttext.load_model(lid_path)\n    lock = {\'config\': config, \'lid_file_sha256\': sha256_file(lid_path),\n            \'packages\': {name: importlib.metadata.version(name) for name in [\'numpy\', \'pandas\', \'scipy\', \'fasttext-wheel\', \'matplotlib\']}}\n    freeze_json(root/\'analysis_lock.json\', lock)\n    frames = {}\n    for study in [\'it2\', \'nllb\', \'madlad\']:\n        collector = Path(config[\'collector_root\'])/study\n        done = json.loads((collector/\'complete.json\').read_text())\n        require(sha256_file(collector/\'all_rows.csv\') == done[\'rows_sha256\'] and\n                sha256_file(collector/\'private_generation/all_outputs.csv\') == done[\'generation_sha256\'], \'Changed generated inputs\')\n        frame = pd.read_csv(collector/\'all_rows.csv\', dtype={\'corpus_sentence_id\': str})\n        path = root/study/\'FG_with_LID.csv\';stamp = path.with_suffix(\'.json\')\n        fingerprint = canonical({\'input\': done, \'analysis\': lock})\n        if stamp.is_file():\n            saved = json.loads(stamp.read_text())\n            require(saved[\'fingerprint\'] == fingerprint and sha256_file(path) == saved[\'sha256\'], \'Changed LID cache\')\n            fg = pd.read_csv(path, dtype={\'corpus_sentence_id\': str})\n        else:\n            texts = pd.read_csv(collector/\'private_generation/all_outputs.csv\', dtype={\'corpus_sentence_id\': str}, keep_default_na=False)\n            labels, probabilities = [], []\n            for i, row in enumerate(texts.itertuples(index=False), 1):\n                require(row.hyp_sha256 == canonical(row.hypothesis), \'Generated text hash changed\')\n                if row.hypothesis.strip():\n                    label, probability = lid.predict(row.hypothesis.replace(\'\\n\', \' \'), k=1)\n                    labels.append(label[0].replace(\'__label__\', \'\'));probabilities.append(float(probability[0]))\n                else:labels.append(\'EMPTY\');probabilities.append(0.)\n                if i % 3000 == 0:progress(f\'{study}: LID {i:,}/18,000\')\n            texts[\'lid_label\'] = labels;texts[\'lid_probability\'] = probabilities\n            texts[\'off_target\'] = texts.lid_label != texts.target\n            fg = frame.merge(texts[[\'pair\', \'sentence_id\', \'lid_label\', \'lid_probability\', \'off_target\']],\n                             on=[\'pair\', \'sentence_id\'], validate=\'one_to_one\')\n            atomic_csv(path, fg);atomic_json(stamp, {\'fingerprint\': fingerprint, \'sha256\': sha256_file(path)})\n        tf_path = Path(config[\'e4_root\'])/\'collectors\'/study/\'all_rows.csv\'\n        require(sha256_file(tf_path) == config[\'TF_sha256\'][study], \'Reference TF metrics changed\')\n        tf = pd.read_csv(tf_path, dtype={\'corpus_sentence_id\': str})\n        frames[(study, \'TF\')], frames[(study, \'FG\')] = tf, fg\n    table = analyze(frames, config[\'split\'], root, config[\'n_boot\'], config[\'seed\'])\n    stats = pd.read_csv(root/\'E6_regime_statistics.csv\')\n    fig, axes = plt.subplots(1, 3, figsize=(13, 4), constrained_layout=True)\n    for ax, metric, title in zip(axes, [\'mean_LM\', \'gradient_fraction\', \'row_direction_share\'],\n                                [\'Lexical mass\', \'Gradient energy fraction\', \'Row variance: direction share\']):\n        for regime, offset in [(\'TF\', -.15), (\'FG\', .15)]:\n            q = stats[(stats.outcome == \'raw_lm\') & (stats.analysis == \'all_common_meanings_descriptive\') &\n                      (stats.regime == regime) & (stats.metric == metric)].set_index(\'study\').loc[[\'it2\', \'nllb\', \'madlad\']]\n            x = np.arange(3)+offset\n            ax.bar(x, q.estimate, width=.28, label=regime)\n            ax.vlines(x, q.ci_low, q.ci_high, colors=\'black\', linewidth=1)\n        ax.set_xticks(np.arange(3), [\'IT2\', \'NLLB\', \'MADLAD\']);ax.set_title(title);ax.legend()\n    for suffix in [\'png\', \'pdf\']:fig.savefig(root/(\'E6_regime_comparison.\'+suffix), dpi=200)\n    plt.close(fig)\n    atomic_json(root/\'status.json\', {\'E6_collection_complete\': True, \'E6_matched_analysis_complete\': True,\n        \'generated_rows\': 54000, \'attention_method\': \'causal replay, cached-decoding parity verified per model\',\n        \'limits\': \'fixed corpus/languages/graph; whole-meaning common support audited; capped rows retained in primary; no quality-estimation claim\'})\n    print(table.to_string(index=False), flush=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser();parser.add_argument(\'--config\', required=True)\n    run(json.loads(Path(parser.parse_args().config).read_text()))\n')


