def pinned_checkout(name,url,revision):
    path=DEPENDENCIES/name
    if not (path/'.git').is_dir():
        path.mkdir(parents=True,exist_ok=True)
        run_live(['git','init',str(path)],environment,'setup.log')
        run_live(['git','-C',str(path),'remote','add','origin',url],environment,'setup.log')
    found=subprocess.run(['git','-C',str(path),'rev-parse','HEAD'],capture_output=True,text=True)
    if found.returncode:
        run_live(['git','-C',str(path),'fetch','--depth','1','origin',revision],environment,'setup.log')
        run_live(['git','-C',str(path),'checkout','--detach',revision],environment,'setup.log')
    require(subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip()==revision,
            'Normalization dependency changed')
    return path
INDIC_LIBRARY=pinned_checkout('indic_nlp_library','https://github.com/anoopkunchukuttan/indic_nlp_library.git',
                             '4cead0ae6c78fe9a19a51ef679f586206df9c476')
INDIC_RESOURCES=pinned_checkout('indic_nlp_resources','https://github.com/anoopkunchukuttan/indic_nlp_resources.git',
                               '5b4ff17c080db4bc4cfc068deaa794aa87562eed')
def completed(study):
    root=OUTPUT_ROOT/'collectors'/study;path=root/'complete.json'
    if not path.is_file():return False
    done=json.loads(path.read_text())
    require(sha256_file(root/'run_lock.json')==done['run_lock_sha256'],'Collector lock changed')
    require(sha256_file(root/'all_rows.csv')==done['rows_sha256'],'Collector metrics changed')
    require(sha256_file(root/'private_generation/all_outputs.csv')==done['generation_sha256'],'Generated paths changed')
    lock=json.loads((root/'run_lock.json').read_text())
    require(lock['sources']==SOURCES and all(lock[k]==v for k,v in COMPLETIONS[study].items()),'Collector provenance changed')
    return True


